SELECT discuss_session_id, turn_ordinal, provider_name, model_id, turn_started_at_ms, turn_completed_at_ms, end_to_end_ms, completion_kind, stop_reason, context_used_tokens, context_window_tokens, harness_cost_amount, harness_cost_currency, harness_cost_kind, usage_is_incomplete, cost_is_partial, evidence_source, evidence_json, created_at_ms
FROM discuss_usage_turns WHERE turn_started_at_ms >= ?1 AND turn_started_at_ms <= ?2 ORDER BY turn_started_at_ms, id;
